#include <stdio.h>

void countOccurrences(int arr[], int n) {
    int freq[1000] = {0};
    for (int i = 0; i < n; i++) freq[arr[i]]++;
    for (int i = 0; i < 1000; i++)
        if (freq[i]) printf("%d -> %d\n", i, freq[i]);
}

