#include <iostream>
#include <unordered_map>
#include <vector>
using namespace std;

unordered_map<int, int> countOccurrences(vector<int>& arr) {
    unordered_map<int, int> freq;
    for (int x : arr) freq[x]++;
    return freq;
}

int main() {
    vector<int> arr = {1, 2, 2, 3, 3, 3, 1};
    for (auto& [k, v] : countOccurrences(arr)) cout << k << " -> " << v << endl;
    return 0;
}
